 "content": "def transform(grid):
    """Extend each non-3 colored center's cross along its full row and column.

    Original nonzero cells (including the 3-cell cross outlines) remain fixed.
    Horizontal rays are drawn first; vertical rays take precedence where they
    cross a horizontal ray.
    """
    h = len(grid)
    w = len(grid[0]) if h else 0
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    centers = [(r, c, original[r][c])
               for r in range(h) for c in range(w)
               if original[r][c] not in (0, 3)]

    for r, c, color in centers:
        for j in range(w):
            if original[r][j] == 0:
                out[r][j] = color

    for r, c, color in centers:
        for i in range(h):
            if original[i][c] == 0:
                out[i][c] = color

    return out

if __name__ == "__main__":
